const TIME_LIMIT: int = 1424;
const OPENING_BUFFER: int = 120;
const LASER_MAILBOX: int = 16;

// Approved moving-Line approximation of GirlA01_at: independent of the dead
// enemy. WAIT60, then ACCEL120 (.05 Easy, .1 otherwise), then coast.
// laserNew(0,0,128,0,16): grow to 128, then translate; width16 -> hit width8.
// The public geometry setters retain the Line's inner 80% collision segment.
async sub line_motion(h: int) {
    var x: fx = lz_x(h);
    var y: fx = lz_y(h);
    var a: angle = lz_angle(h);
    var speed: fx = 0.4fx;
    var accel: fx = 0.1fx;
    if global(GVAR_RANK) == RANK_EASY { accel = 0.05fx; }
    // Set rod capacity once; default zero rod length would collapse the segment.
    lz_speed(h, 0fx, 128fx);
    var travel: fx = 0fx;
    var age: int = 0;
    loop {
        if lz_alive(h) == 0 { return; }
        if age >= 60 && age < 180 { speed = speed + accel; }
        travel = travel + speed;
        var len: fx = travel;
        if len > 128fx { len = 128fx; }
        var tail: fx = travel - len;
        // Whole rod is beyond a conservative playfield margin, including tail.
        // No arbitrary lifetime cutoff; slow Easy rods keep their full transit.
        var tx: fx = x + tail * cos(a);
        var ty: fx = y + tail * sin(a);
        if ty > 576fx || tx < -320fx || tx > 320fx {
            lz_cancel(h);
            return;
        }
        lz_origin(h, tx, ty);
        // Raising near above far raises far; restore near after setting far.
        lz_start(h, len * 0.9fx);
        lz_start(h, len * 0.1fx);
        age = age + 1;
        wait(1);
    }
}

// A control-owned observer takes only the handles. Each enemy writes its own
// five slots once, so callbacks never depend on a retired enemy's task lifetime.
async sub keep_tail(slot: int) {
    while global(slot) == 0 { wait(1); }
    var n: int = global(slot);
    for k in 0..n {
        spawn line_motion(global(slot + 1 + k));
    }
}

sub death_line(slot: int, k: int, a: angle) {
    // Source etSprite(0,8,2): built-in laser rendering, source color2.
    // Line L>16 gate: 40 ticks at .4 plus 1-2 task-start ticks.
    // A 42-frame warning avoids collision while the rod is too short.
    var h: int = laser(2, $self_x, $self_y, a, 0fx, 8fx, 42, 1300, 0);
    set_global(slot + 1 + k, h);
}

async sub girl(slot: int) {
    set_invuln(65535);
    set_hurtbox(12fx); // GirlA01F: setHurtbox(24,24)
    set_hitbox(8fx);   // setHitbox(16,16)
    // F2 is sampled from the actual creation position before mirror movement.
    var f2: angle = atan2(448fx - $self_y, 0fx - $self_x);
    var dir: angle = 180deg - f2;
    // enmCreateM sets child mirror; 404/405 reflect angle, not coordinates.
    move_vel(0, 90deg, 1fx, EASE_LINEAR);
    move_vel(60, dir, 2fx, EASE_LINEAR);
    wait(120);
    // Approved fixed enemy-age120 substitute for source setDeath callback.
    // Source 386-397: E/N center, H +/-10deg, L adds +/-30deg.
    if global(GVAR_RANK) < RANK_HARD {
        death_line(slot, 0, dir);
        set_global(slot, 1);
    } else {
        death_line(slot, 0, dir - 10deg);
        death_line(slot, 1, dir + 10deg);
        if global(GVAR_RANK) == RANK_LUNATIC {
            death_line(slot, 2, dir - 30deg);
            death_line(slot, 3, dir + 30deg);
            set_global(slot, 4);
        } else { set_global(slot, 2); }
    }
    // Main-task return removes this emitter once; lasers remain independent.
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wait(60); // MainSub02:1345, card source-frame0 is before this wait.
    var id: int = 0;
    for round in 0..2 {
        var x: fx = -120fx;
        for i in 0..10 {
            var slot: int = LASER_MAILBOX + id * 5;
            set_global(slot, 0);
            spawn keep_tail(slot);
            _ = spawn_enemy(x, -24fx, 70, 0, 0, 162, girl(slot));
            id = id + 1;
            x = x + 24fx;
            wait(10);
        }
        // The second sweep starts at +120, not +96; preserve F after loop.
        for j in 0..10 {
            var slot_back: int = LASER_MAILBOX + id * 5;
            set_global(slot_back, 0);
            spawn keep_tail(slot_back);
            _ = spawn_enemy(x, -24fx, 70, 0, 0, 162, girl(slot_back));
            id = id + 1;
            x = x - 24fx;
            wait(10);
        }
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
